{% if call.name.ends_with?("=") %}
        def {{ call.name }}(value)
          __setattr__({{ call.name.stringify }}, value.to_py)
        end
      {% else %}
        def {{ call.name }}(*args, **kwargs)
          call({{ call.name.stringify }}, *args, **kwargs)
        end
      {% end %}
